import { createHash } from 'node:crypto';
const sha=v=>createHash('sha256').update(JSON.stringify(v),'utf8').digest('hex');
export function stageCandidateArtifactV1({bytesIdentity,producerReceipt,securityDomain}={}){if(typeof bytesIdentity!=='string'||!bytesIdentity)throw new Error('CONTENT_IDENTITY_REQUIRED');if(!producerReceipt||producerReceipt.status!=='PASS')throw new Error('PRODUCER_RECEIPT_REQUIRED');if(typeof securityDomain!=='string'||!securityDomain)throw new Error('SECURITY_DOMAIN_REQUIRED');const body={schemaId:'CANDIDATE_ARTIFACT_V1',bytesIdentity,producerReceiptDigest:sha(producerReceipt),securityDomain,authoritativeEvidence:false,verifierPass:false};return Object.freeze({...body,candidateDigest:sha(body)});}
export function evaluateCacheReuseV1({candidate,requiredSecurityDomain}={}){if(!candidate||candidate.schemaId!=='CANDIDATE_ARTIFACT_V1')return Object.freeze({reusable:false,code:'CANDIDATE_REQUIRED'});if(candidate.securityDomain!==requiredSecurityDomain)return Object.freeze({reusable:false,code:'SECURITY_DOMAIN_MISMATCH'});return Object.freeze({reusable:true,code:'CACHE_REUSE_ALLOWED_FINAL_GATE_STILL_REQUIRED',verifierPass:false,authoritativeEvidence:false});}
